import java.io.File;
import java.nio.file.Path;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new file inside {@code dir} with a sanitized {@code name}.
     * The method ensures that the resulting file cannot escape the specified
     * directory, preventing directory‑traversal attacks.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters (e.g., "?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve and normalize the target path
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Verify that the target path is still inside the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "Invalid file name: " + name + " (path traversal detected)");
        }

        File file = targetPath.toFile();

        // Split the name into prefix and suffix for uniqueness handling
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            targetPath = dirPath.resolve(newName).normalize();
            file = targetPath.toFile();
        }

        // Ensure the parent directory exists
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
