public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    protected void extractFile(final File srcF, final File dir, final InputStream compressedInputStream,
                               final String entryName, final Date entryDate, final boolean isDirectory,
                               final Integer mode, String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file
        final File f = FileUtils.resolveFile(dir, entryName);

        // Ensure the resolved file stays within the target directory (prevent Zip‑Slip)
        Path canonicalDirPath = dir.getCanonicalFile().toPath();
        Path canonicalDestPath = f.getCanonicalFile().toPath();
        if (!canonicalDestPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException("Entry is outside of the target directory (" + entryName + ")");
        }

        try {
            // Skip extraction if overwrite is disabled and the existing file is newer or equal
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Create a symbolic link
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                // Create the directory
                f.mkdirs();
            } else {
                // Extract the file contents
                try (OutputStream out = new FileOutputStream(f)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time
            f.setLastModified(entryDate.getTime());

            // Apply permissions if requested
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(f, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + f.getPath());
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }

}
