public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path so that it always starts with a single leading slash.
     * <p>
     * The original implementation only removed excess leading slashes but never
     * added one if the path was missing it. This could cause the path to be
     * interpreted as another URI component (e.g., host) when the resulting
     * string was used to construct a {@link java.net.URI}. The updated method
     * guarantees that the returned path is non‑null, non‑empty, and begins
     * with exactly one '/' character. It also preserves the rest of the path
     * unchanged, ensuring that legitimate paths such as "/foo/bar" remain
     * unaffected.
     *
     * @param path the raw path component; may be {@code null}
     * @return a normalized path starting with a single '/', or {@code null}
     *         if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Count leading slashes
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Keep the rest of the string after all leading slashes
        String rest = path.substring(i);

        // Ensure there is exactly one leading slash
        if (rest.isEmpty()) {
            // Path was all slashes or empty – return a single slash
            return "/";
        }

        // If the remaining part already starts with a slash, we had more than
        // one leading slash originally; keep only one.
        if (rest.charAt(0) == '/') {
            return rest;
        }

        // Otherwise prepend a single slash
        return '/' + rest;
    }

