    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        /* 
         * Track progress to avoid infinite loops caused by repeated
         * unmappable/malformed input.  If the encoder fails to consume
         * any input during an iteration, we skip the offending
         * character(s) and continue.  A hard limit on consecutive
         * failures protects against pathological input.
         */
        int consecutiveErrorCount = 0;
        final int MAX_CONSECUTIVE_ERRORS = 3;

        while (cb.remaining() > 0) {
            int prevPos = cb.position();
            CoderResult res = enc.encode(cb, out, false);

            if (res.isError()) {
                /* Handle overflow separately – we simply grow the buffer. */
                if (res.isOverflow()) {
                    int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                    out = ZipEncodingHelper.growBufferBy(out, increment);
                    continue;
                }

                /* For malformed or unmappable input we must make progress. */
                if (cb.position() == prevPos) {
                    /* No progress – skip one character to avoid a stall. */
                    consecutiveErrorCount++;
                    if (consecutiveErrorCount > MAX_CONSECUTIVE_ERRORS) {
                        throw new CharacterCodingException();
                    }

                    /* Ensure there is space for a replacement byte. */
                    if (!out.hasRemaining()) {
                        out = ZipEncodingHelper.growBufferBy(out, estimateIncrementalEncodingSize(enc, 1));
