import java.io.IOException;
import java.util.Hashtable;
import javax.naming.CommunicationException;
import javax.naming.Context;
import javax.naming.NamingException;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import javax.net.ssl.SSLSocketFactory;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider
{
    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that authenticates the supplied principal and credentials
     * over a STARTTLS protected connection.  The method performs the following steps:
     *
     * <ol>
     *   <li>Creates an anonymous LDAP context.</li>
     *   <li>Negotiates STARTTLS and obtains the {@link SSLSocketFactory} used for the TLS session.</li>
     *   <li>Closes the anonymous context.</li>
     *   <li>Re‑creates a new context using the TLS socket factory and supplies the supplied
     *       principal/credentials for a proper bind.</li>
     * </ol>
     *
     * This guarantees that authentication occurs **after** the TLS handshake, preventing
     * attackers from exploiting an unauthenticated connection.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the distinguished name to bind as
     * @param credentials        the password for the principal
     * @return an authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or bound
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {

        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        try {
            // Step 1: create an anonymous context
            ctx = new InitialLdapContext(env, null);

            // Step 2: negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // performs the TLS handshake
            SSLSocketFactory sslSocketFactory = tls.getSSLSocketFactory();

            // Step 3: close the anonymous context
            LdapUtils.closeContext(ctx);
            ctx = null;

            // Step 4: build a new environment that includes the TLS socket factory
            Hashtable<String, Object> authEnv = new Hashtable<>(env);
            authEnv.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
            authEnv.put(Context.SECURITY_PRINCIPAL, principal);
            authEnv.put(Context.SECURITY_CREDENTIALS, credentials);
            authEnv.put("com.sun.jndi.ldap.connect.socketFactory", sslSocketFactory);

            // Recreate the context with authentication credentials
            return new InitialLdapContext(authEnv, null);

        } catch (IOException e) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), e));
            throw new CommunicationException(e.getMessage());
        } catch (Throwable t) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), t));
            throw t;
        }
    }

    // other methods
}
