public class Expander {

    // other methods

    /**
     * Safely expands the contents of an archive into {@code targetDirectory}.
     *
     * <p>All entry names are validated to prevent path‑traversal attacks. The method uses
     * canonical paths for both the target directory and each entry to guarantee that
     * no file is written outside the intended extraction root. It also rejects
     * absolute paths, names containing {@code ..}, and entries whose parent directory
     * is a symbolic link.</p>
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the extraction root once.
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            /* --------------------------------------------------------------------
             * 1. Basic sanity checks on the entry name
             * -------------------------------------------------------------------- */
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("Archive entry has empty name");
            }
            // Reject absolute paths (both Unix and Windows styles)
            if (entryName.startsWith(File.separator) || entryName.startsWith("\\") || entryName.matches("^[A-Za-z]:[\\\\/]")) {
                throw new IOException("Archive entry contains absolute path: " + entryName);
            }
            // Reject names that attempt directory traversal
            if (entryName.contains("..")) {
                throw new IOException("Archive entry contains path traversal component: " + entryName);
            }

            /* --------------------------------------------------------------------
             * 2. Construct the target file and verify it stays within the root
             * -------------------------------------------------------------------- */
            File f = new File(targetDirectory, entryName);
            // Resolve canonical path to collapse any remaining '..' or symlinks
            String canonicalFilePath = f.getCanonicalPath();
            if (!canonicalFilePath.startsWith(targetDirCanonical)) {
                throw new IOException("Expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            /* --------------------------------------------------------------------
             * 3. Prevent writing under a symbolic link
             * -------------------------------------------------------------------- */
            File parent = f.getParentFile();
            if (parent != null && Files.isSymbolicLink(parent.toPath())) {
                throw new IOException("Parent directory of " + entryName + " is a symbolic link");
            }

            /* --------------------------------------------------------------------
             * 4. Perform the actual extraction
             * -------------------------------------------------------------------- */
